TWComponent.script:
function addSQLParameter(value){
	if(value == null && typeof value == "string"){
		value= ""; 
	}
	else if(value == null && typeof value == "number"){
		value= 0;
	}
	else if(value == null && typeof value == "boolean"){
		value = "0";
	}
 var parameter = new tw.object.SQLParameter();  
   parameter.value = value;
   parameter.mode = "IN";
return parameter;
}

tw.local.sqlStatements = new tw.object.listOf.SQLStatement();
var sqlStatementLen = 0;
if(!!tw.local.odcRequest.FcCollections) {
  if(!! tw.local.odcRequest.FcCollections.selectedTransactions){
     
     for (var i = 0 ;i <  tw.local.odcRequest.FcCollections.selectedTransactions.listLength;i++) {

            sqlStatementLen = tw.local.sqlStatements.listLength? tw.local.sqlStatements.listLength:0;
       
            tw.local.sqlStatements[sqlStatementLen]= new tw.object.toolkit.TWSYS.SQLStatement();

      	tw.local.sqlStatements[sqlStatementLen].sql = "INSERT INTO "+ tw.env.LKP_DB_Schema + ".ODC_FCTRANSACTION"
                                                          +" (ACCOUNTNO,POSTINGDATE,VALUEDATE,TRANSACTIONAMOUNT,AMOUNTINBPM, REQUESRID)"
                                                          +" VALUES (?,?,?,?,?,?)";
			
 	tw.local.sqlStatements[sqlStatementLen].parameters = new tw.object.listOf.toolkit.TWSYS.SQLParameter();
 	
	
	tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.odcRequest.FcCollections.selectedTransactions[i].accountNo  ));
	tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.odcRequest.FcCollections.selectedTransactions[i].postingDate  ));	
	tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.odcRequest.FcCollections.selectedTransactions[i].valueDate) );
      tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.odcRequest.FcCollections.selectedTransactions[i].transactionAmount ) ); 
      tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.odcRequest.FcCollections.selectedTransactions[i].existAmount ) ); 
      tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.odcRequest.requestNo) ); 
       } 
    } 

}

tw.local.sqlStatements=  new tw.object.listOf.toolkit.TWSYS.SQLStatement();
/**-------------------------- Add SQL Parameters --------------------------**/
function addSQLParameter(value){
	if(value == null && typeof value == "string"){
		value= ""; 
	}
	else if(value == null && typeof value == "number"){
		value= 0;
	}
	else if(value == null && typeof value == "boolean"){
		value = "0";
	}
 var parameter = new tw.object.SQLParameter();  
   parameter.value = value;
   parameter.mode = "IN";
return parameter;
}


var sqlStatementLen= 0;

function DeleteRecordsByID(tableName){
	 
	sqlStatementLen = tw.local.sqlStatements.listLength? tw.local.sqlStatements.listLength:0;
	tw.local.sqlStatements[sqlStatementLen]= new tw.object.toolkit.TWSYS.SQLStatement();
	
	tw.local.sqlStatements[sqlStatementLen].sql = " DELETE FROM "+ tw.env.LKP_DB_Schema + "."+ tableName + " WHERE REQUESTNO= ? ";
			
	tw.local.sqlStatements[sqlStatementLen].parameters = new tw.object.listOf.toolkit.TWSYS.SQLParameter();
	tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.odcRequest.requestNo));
  	 
}

DeleteRecordsByID (   "ODC_FCTransaction"   );

